    {
      base.OnEnable();
    }

    protected override void OnDisable()
    {
      base.OnDisable();
    }

    protected override void OnSkillQuery(SkillQueryData data)
    {
      if (data.queryType == SkillQueryType.GetMaxAttackCount)
      {
        data.intValue = GetMaxAttackCount();
      }
