          EventChannelLocator.MainContainer.poolOperationChannel.Raise(
              PoolOperationData.CreateAddMultiple(ObjectPoolConst.ImpactCannonHitWinterPool, impactCannonHitWinterPrefab, 20));
          break;
        case Element.Grass:
