using System.Collections.Generic;
using System.Reflection;
using Controllers.Character;
using UnityEngine;
using XLua;

namespace Controllers.Rune
{
    /// <summary>
    /// 符文效果应用器。读取 RuneEquipmentSnapshot 中缓存的装备符文 ID，
    /// 优先从 Lua 热更新配置加载数值和效果映射，Lua 不可用时回退到 C# 硬编码。
    /// </summary>
    public static class RuneEffectApplier
    {
        // Lua 热更新模块缓存（避免每帧重复加载）
        private static LuaTable _luaMain;
        private static bool _luaLoaded;

        /// <summary>将已装备符文的效果应用到玩家属性上</summary>
        public static void ApplyEquippedRunes(AttributePlayerBase attributes)
        {
            var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
            if (database == null || database.allRunes == null || database.allRunes.Count == 0)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到 RuneDatabase 或数据为空");
                return;
            }

            int[] equippedIds = RuneEquipmentSnapshot.GetAllEquippedIds();
            if (equippedIds.Length == 0)
            {
                Debug.Log("[RuneEffectApplier] 未装备任何符文");
                return;
            }

            // 加载 Lua 热更新配置（仅首次成功后缓存）
            LoadLuaConfig();

            string currentCharacterType = DetectCurrentCharacterType();

            foreach (int runeId in equippedIds)
            {
                // ── 尝试从 Lua 热更新配置获取覆盖值 ──
                LuaTable luaRuneConfig = GetLuaRuneConfig(runeId);

                if (luaRuneConfig != null)
                {
                    Debug.Log($"[RuneEffectApplier] 应用符文效果(Lua热更新): ID={runeId}");
                    ApplyFromLuaConfig(attributes, luaRuneConfig, currentCharacterType);
                }
                else
                {
                    // 回退到 ScriptableObject 默认值
                    var runeData = database.GetRuneById(runeId);
                    if (runeData == null)
                    {
                        Debug.LogWarning($"[RuneEffectApplier] 未在数据库中找到符文 ID: {runeId}");
                        continue;
                    }

                    Debug.Log($"[RuneEffectApplier] 应用符文效果(默认): {runeData.runeName} (ID={runeId})");
                    ApplyFromSO(attributes, runeData, currentCharacterType);
                }
            }

            LogFinalAttributes(attributes);
        }

        // ────────────────────────────────────
        //  Lua 配置加载
        // ────────────────────────────────────

        private static void LoadLuaConfig()
        {
            if (_luaLoaded) return;

            try
            {
                var luaEnv = LuaEnvManager.Instance.LuaEnv;
                if (luaEnv == null)
                {
                    Debug.LogWarning("[RuneEffectApplier] LuaEnv 未初始化，使用 C# 默认配置");
                    return;
                }

                var result = luaEnv.DoString("return require('Main')");
                if (result != null && result.Length > 0)
                {
                    _luaMain = result[0] as LuaTable;
                    _luaLoaded = true;
                    Debug.Log("[RuneEffectApplier] Lua 符文配置加载成功");
                }
            }
            catch (System.Exception e)
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 加载失败，使用 C# 默认配置: {e.Message}");
            }
        }

        private static LuaTable GetLuaRuneConfig(int runeId)
        {
            if (_luaMain == null) return null;
            var runeConfig = _luaMain.Get<LuaTable>("RuneConfig");
            return runeConfig?.Get<int, LuaTable>(runeId);
        }

        // ────────────────────────────────────
        //  公共 API：供 UI 查询热更新后的有效数值
        // ────────────────────────────────────

        /// <summary>获取符文的有效属性数值（优先 Lua 热更新，回退 SO 默认值）</summary>
        public static List<RunePower> GetEffectivePowers(int runeId)
        {
            LoadLuaConfig();

            LuaTable luaConfig = GetLuaRuneConfig(runeId);
            if (luaConfig != null)
            {
                var powersTable = luaConfig.Get<LuaTable>("powers");
                int len = powersTable != null ? powersTable.Length : 0;
                if (len > 0)
                {
                    var result = new List<RunePower>(len);
                    for (int i = 1; i <= len; i++)
                    {
                        var power = powersTable.Get<int, LuaTable>(i);
                        if (power == null) continue;
                        result.Add(new RunePower
                        {
                            label = power.Get<string>("label"),
                            value = power.Get<int>("value")
                        });
                    }
                    if (result.Count > 0) return result;
                }
            }

            // 回退到 SO 默认值
            var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
            return database?.GetRuneById(runeId)?.powers ?? new List<RunePower>();
        }

        /// <summary>获取符文的有效特殊技能名（优先 Lua，回退 SO）</summary>
        public static string GetEffectiveSpecialPowerName(int runeId)
        {
            LoadLuaConfig();

            var luaConfig = GetLuaRuneConfig(runeId);
            if (luaConfig != null)
            {
                string name = luaConfig.Get<string>("specialPowerName");
                if (!string.IsNullOrEmpty(name)) return name;
            }

            var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
            return database?.GetRuneById(runeId)?.specialPowerName ?? string.Empty;
        }

        /// <summary>获取符文的有效特殊技能描述（优先 Lua，回退 SO）</summary>
        public static string GetEffectiveSpecialPowerDescription(int runeId)
        {
            LoadLuaConfig();

            var luaConfig = GetLuaRuneConfig(runeId);
            if (luaConfig != null)
            {
                string desc = luaConfig.Get<string>("specialPowerDescription");
                if (!string.IsNullOrEmpty(desc)) return desc;
            }

            var database = Resources.Load<RuneDatabaseSO>("RuneData/RuneDatabase");
            return database?.GetRuneById(runeId)?.specialPowerDescription ?? string.Empty;
        }

        // ────────────────────────────────────
        //  Lua 路径：从 Lua 配置应用效果
        // ────────────────────────────────────

        private static void ApplyFromLuaConfig(AttributePlayerBase attr, LuaTable luaConfig, string currentCharType)
        {
            // 1. 应用基础 powers（数值 + 效果映射均来自 Lua）
            var powersTable = luaConfig.Get<LuaTable>("powers");
            int powerLen = powersTable != null ? powersTable.Length : 0;
            for (int i = 0; i < powerLen; i++)
            {
                var power = powersTable.Get<int, LuaTable>(i + 1); // Lua 索引从 1 开始
                if (power == null) continue;

                string label = power.Get<string>("label");
                int value = power.Get<int>("value");

                ApplyPowerFromLua(attr, label, value);
            }

            // 2. 应用特殊技能
            string specialName = luaConfig.Get<string>("specialPowerName");
            if (!string.IsNullOrEmpty(specialName))
            {
                ApplySpecialPowerFromLua(attr, luaConfig, specialName, currentCharType);
            }
        }

        private static void ApplyPowerFromLua(AttributePlayerBase attr, string label, int value)
        {
            if (_luaMain == null)
            {
                // 回退到 C# switch-case
                ApplyPower(attr, new RunePower { label = label, value = value });
                return;
            }

            var effectMap = _luaMain.Get<LuaTable>("RuneEffect");
            string methodName = effectMap?.Get<string>(label);

            if (string.IsNullOrEmpty(methodName))
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 未识别的符文效果标签: '{label}'，回退到 C#");
                ApplyPower(attr, new RunePower { label = label, value = value });
                return;
            }

            // 反射调用 AttributePlayerBase 的方法
            var method = typeof(AttributePlayerBase).GetMethod(
                methodName, BindingFlags.Public | BindingFlags.Instance);
            if (method != null)
            {
                method.Invoke(attr, new object[] { value });
                Debug.Log($"[RuneEffectApplier] Lua映射: {label} → {methodName}({value})");
            }
            else
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 映射的方法不存在: {methodName}");
            }
        }

        private static void ApplySpecialPowerFromLua(AttributePlayerBase attr, LuaTable luaConfig,
            string specialName, string currentCharType)
        {
            // 角色匹配检查
            string exclusiveType = luaConfig.Get<string>("exclusiveCharacterType");
            if (!string.IsNullOrEmpty(exclusiveType) && exclusiveType != currentCharType)
            {
                Debug.Log($"[RuneEffectApplier] 跳过专属符文效果 [{specialName}]：角色不匹配");
                return;
            }

            if (_luaMain == null) return;

            var specialPowers = _luaMain.Get<LuaTable>("RuneSpecialPower");
            LuaFunction luaFunc = specialPowers?.Get<LuaFunction>(specialName);

            if (luaFunc != null)
            {
                luaFunc.Call(attr);
                luaFunc.Dispose();
                Debug.Log($"[RuneEffectApplier] Lua特殊技能: {specialName} 已应用");
            }
            else
            {
                Debug.LogWarning($"[RuneEffectApplier] Lua 未定义的特殊技能: '{specialName}'");
            }
        }

        // ────────────────────────────────────
        //  C# 回退路径：原有逻辑保持不变
        // ────────────────────────────────────

        private static void ApplyFromSO(AttributePlayerBase attr, RuneDataSO runeData, string currentCharType)
        {
            foreach (var power in runeData.powers)
            {
                ApplyPower(attr, power);
            }

            if (!string.IsNullOrEmpty(runeData.specialPowerDescription))
                ApplySpecialPower(attr, runeData, currentCharType);
        }

        private static void ApplyPower(AttributePlayerBase attr, RunePower power)
        {
            switch (power.label)
            {
                case "%基础伤害":
                    attr.AddAttackPower(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击力 +{power.value}% → {attr.GetAttackPower()}");
                    break;

                case "%暴击率":
                    attr.AddCriticalChance(power.value);
                    Debug.Log($"[RuneEffectApplier] 暴击率 +{power.value}% → {attr.GetCriticalChance() * 100:F1}%");
                    break;

                case "%防御力":
                    attr.AddDefensePower(power.value);
                    Debug.Log($"[RuneEffectApplier] 防御力 +{power.value}% → {attr.GetDefensePower()}");
                    break;

                case "%攻击速度":
                    attr.ReduceAttackInterval(power.value);
                    Debug.Log($"[RuneEffectApplier] 攻击速度 +{power.value} → {attr.GetAttackSpeed()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未识别的符文效果标签: '{power.label}'");
                    break;
            }
        }

        private static void ApplySpecialPower(AttributePlayerBase attr, RuneDataSO runeData, string currentCharacterType)
        {
            if (!string.IsNullOrEmpty(runeData.exclusiveCharacterType))
            {
                if (runeData.exclusiveCharacterType != currentCharacterType)
                {
                    Debug.Log($"[RuneEffectApplier] 跳过专属符文效果 [{runeData.specialPowerName}]："
                              + $"角色 {currentCharacterType} 与符文专属角色 {runeData.exclusiveCharacterType} 不匹配");
                    return;
                }
                Debug.Log($"[RuneEffectApplier] 专属符文效果匹配！角色 {currentCharacterType} ✅");
            }

            Debug.Log($"[RuneEffectApplier] 应用特殊技能: {runeData.specialPowerName} → {runeData.specialPowerDescription}");

            switch (runeData.specialPowerName)
            {
                case "小法师专属：":
                    attr.AddMaxAttackCount(1);
                    attr.AddComboCount(1);
                    Debug.Log($"[RuneEffectApplier] 初始发射数量 +1 → {attr.GetMaxAttackCount()}");
                    break;

                default:
                    Debug.LogWarning($"[RuneEffectApplier] 未处理的特殊技能: '{runeData.specialPowerDescription}'");
                    break;
            }
        }

        // ────────────────────────────────────
        //  工具方法
        // ────────────────────────────────────

        private static string DetectCurrentCharacterType()
        {
            var player = Object.FindObjectOfType<PlayerController>();
            if (player == null)
            {
                Debug.LogWarning("[RuneEffectApplier] 未找到场景中的 PlayerController，无法检测角色类型");
                return string.Empty;
            }

            string typeName = player.GetType().Name;
            Debug.Log($"[RuneEffectApplier] 检测到当前角色类型: {typeName}");
            return typeName;
        }

        private static void LogFinalAttributes(AttributePlayerBase attr)
        {
            Debug.Log($"[RuneEffectApplier] ── 符文应用后最终属性 ──\n" +
                      $"攻击力: {attr.GetAttackPower()}\n" +
                      $"防御力: {attr.GetDefensePower()}\n" +
                      $"暴击率: {attr.GetCriticalChance() * 100:F1}%\n" +
                      $"攻击间隔: {attr.GetAttackInterval()}\n" +
                      $"移动速度: {attr.GetMoveSpeed()}");
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using Core;
using Core.Channels.Game;
using Core.Channels.General;
using Core.Channels.Player;
using Controllers.Item;
using Core;
using Controllers.Services;
using NetworkTarget = Controllers.Network.NetworkTarget;
using Controllers.Network;
using UI;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Managers
{
    /// <summary>
    /// 经验值/升级业务逻辑（Application 层）
    ///
    /// 职责：
    /// - 管理经验值增减、升级计算
    /// - 维护升级队列，逐级处理
    /// - 通过 RPC 同步经验/等级到所有客户端
    /// - 通过 EventChannel 与 Presentation 层通信
    ///
    /// 通信方式：
    /// 输入 → experienceChannel（拾取经验球）
    /// 输入 → gameActionChannel（升级确认操作）
    /// 输入 → skillQueryChannel（升级经验查询）
    /// 输出 → experienceUpdateChannel（更新 UI）
    /// 输出 → magicUpgradeChannel（开关升级面板）
    /// </summary>
    public class ExperienceManager : MonoBehaviour
    {
        public static ExperienceManager Instance { get; private set; }

        void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
            }
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ========== 升级队列系统 ==========
        private Queue<int> pendingLevelUps = new Queue<int>();
        private bool isProcessingLevelUp = false;

        // 经验/等级状态
        private int currentExperience;
        private int currentLevel;
        private int upgradeExperience;

        // ========== 经验球非网络化（方案二） ==========
        /// <summary>下一个可用的 ballId 自增计数器（仅房主使用）</summary>
        private uint nextBallId = 1;

        /// <summary>已认领的球 ID 集合，防止重复计数（仅房主使用）</summary>
        private HashSet<uint> claimedBalls = new HashSet<uint>();

        /// <summary>当前活跃的本地经验球映射 ballId → GameObject（所有客户端使用）</summary>
        private Dictionary<uint, GameObject> activeExpBalls = new Dictionary<uint, GameObject>();

        // 专属卡牌升级倍数奖励：记录当前选卡对应的等级，用于判断是否触发 3 级额外奖励
        private int lastBonusCheckLevel = -1;

        void OnEnable()
        {
            if (EventChannelLocator.MainContainer.gameSettings.IsTest)
            {
                Initialize();
            }
            SceneManager.sceneLoaded += OnSceneLoaded;
            EventChannelLocator.MainContainer.gameActionChannel.RegisterListener(OnGameActionReceived);
            EventChannelLocator.MainContainer.experienceChannel.RegisterListener(OnExperienceReceived);
            EventChannelLocator.MainContainer.skillQueryChannel.RegisterListener(OnSkillQuery);
        }

        void OnDisable()
        {
            SceneManager.sceneLoaded -= OnSceneLoaded;
            EventChannelLocator.MainContainer.gameActionChannel.UnregisterListener(OnGameActionReceived);
            EventChannelLocator.MainContainer.experienceChannel.UnregisterListener(OnExperienceReceived);
            EventChannelLocator.MainContainer.skillQueryChannel.UnregisterListener(OnSkillQuery);

            // 清理经验球状态
            activeExpBalls.Clear();
            claimedBalls.Clear();
        }

        private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
        {
            if (scene.buildIndex > 1)
            {
                Initialize();
            }
        }

        private void OnSkillQuery(SkillQueryData data)
        {
            if (data.queryType == SkillQueryType.GetUpgradeExperience)
            {
                data.intValue = upgradeExperience;
            }
        }

        private void OnGameActionReceived(GameActionType actionType)
        {
            switch (actionType)
            {
                case GameActionType.UpgradeAllConfirmed:
                    OnPlayerUpgradeChoiceConfirmed();
                    break;
            }
        }

        private void Initialize()
        {
            upgradeExperience = 100;

            // 重置经验球去重状态
            nextBallId = 1;
            claimedBalls.Clear();

            RaiseExperienceUpdate();
        }

        #region 经验条相关

        public int GetUpgradeExperience()
        {
            return upgradeExperience;
        }

        private void OnExperienceReceived(int experience)
        {
            AddExperience(experience);
        }

        /// <summary>
        /// 发送经验/等级更新事件到 Presentation 层
        /// </summary>
        private void RaiseExperienceUpdate()
        {
            var data = new ExperienceUpdateData(currentExperience, upgradeExperience, currentLevel);
            EventChannelLocator.MainContainer.experienceUpdateChannel.Raise(data);
        }

        public void AddExperience(int experience)
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsTest && !NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                return;
            }

            currentExperience += experience;

            // 记录本次获得的经验到对局统计
            MatchStatisticsManager.Instance?.RecordExperience(experience);
            QuestTaskManager.Instance?.RecordExp();

            CheckAndQueueUpgrades();
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_SyncExperience", NetworkTarget.All, currentExperience);

            if (pendingLevelUps.Count > 0 && !isProcessingLevelUp)
            {
                StartLevelUpSequence();
            }
        }

        private void StartLevelUpSequence()
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsTest)
            {
                if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                {
                    return;
                }
            }

            isProcessingLevelUp = true;
            ProcessNextLevelUp();
        }

        private void ProcessNextLevelUp()
        {
            if (pendingLevelUps.Count == 0)
            {
                CompleteAllLevelUps();
                return;
            }

            int levelForThisChoice = pendingLevelUps.Dequeue();
            lastBonusCheckLevel = levelForThisChoice; // 保存等级供面板关闭时检查倍数奖励
            StartCoroutine(OpenMagicUpgradePanelWithDelay());
        }

        IEnumerator OpenMagicUpgradePanelWithDelay()
        {
            yield return new WaitForSeconds(1f);
            if (EventChannelLocator.MainContainer.gameSettings.IsTest)
            {
                EventChannelLocator.MainContainer.magicUpgradeChannel.Raise(true);
                yield break;
            }
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "OpenMagicUpgradePanel", NetworkTarget.All);
        }

        private void CheckAndQueueUpgrades()
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsTest)
            {
                if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                {
                    return;
                }
            }

            while (currentExperience >= upgradeExperience)
            {
                int requiredExp = upgradeExperience;

                if (EventChannelLocator.MainContainer.gameSettings.IsTest)
                {
                    HandleIncreaseLevelRPC(requiredExp);
                }
                else
                {
                    NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "IncreaseLevel", NetworkTarget.All, requiredExp);
                }

                pendingLevelUps.Enqueue(currentLevel);
            }

            // 通过事件通道更新等级显示
            RaiseExperienceUpdate();
        }

        private void CompleteAllLevelUps()
        {
            isProcessingLevelUp = false;
            Debug.Log("所有升级处理完毕");
        }

        public void OnPlayerUpgradeChoiceConfirmed()
        {
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "CloseMagicUpgradePanel", NetworkTarget.All);
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用
        /// 关闭升级面板并在 Master 客户端启动下一级升级流程
        /// 每 3 级额外触发一次专属卡牌升级（三张不重复专属卡牌）
        /// </summary>
        public static void HandleCloseMagicUpgradePanelRPC()
        {
            EventChannelLocator.MainContainer.magicUpgradeChannel.Raise(false);
            if (Instance != null && NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                // 每升级 3 次（3、6、9...级）额外赠送一次专属卡牌升级
                if (Instance.lastBonusCheckLevel > 0 && Instance.lastBonusCheckLevel % 3 == 0)
                {
                    Instance.lastBonusCheckLevel = -1; // 防止重复触发
                    Instance.StartCoroutine(Instance.OpenExUpgradePanelWithDelay());
                }
                else
                {
                    Instance.lastBonusCheckLevel = -1;
                    Instance.StartCoroutine(Instance.DelayedProcessNextLevelUp());
                }
            }
        }

        private IEnumerator DelayedProcessNextLevelUp()
        {
            yield return new WaitForSeconds(0.5f);
            ProcessNextLevelUp();
        }

        /// <summary>
        /// 专属卡牌升级面板：延迟后打开，显示三张不重复专属卡牌
        /// </summary>
        private IEnumerator OpenExUpgradePanelWithDelay()
        {
            yield return new WaitForSeconds(1f);
            if (EventChannelLocator.MainContainer.gameSettings.IsTest)
            {
                if (MagicUpgradeManager.instance != null)
                    MagicUpgradeManager.instance.isAllExCard = true;
                EventChannelLocator.MainContainer.magicUpgradeChannel.Raise(true);
                yield break;
            }
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "OpenExMagicUpgradePanel", NetworkTarget.All);
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：同步经验值到所有客户端
        /// </summary>
        public static void HandleSyncExperienceRPC(int syncedExp)
        {
            if (Instance == null) return;
            Instance.currentExperience = syncedExp;
            Instance.RaiseExperienceUpdate();
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：增加等级
        /// </summary>
        public static void HandleIncreaseLevelRPC(int requiredExp)
        {
            if (Instance == null) return;
            Instance.currentExperience -= requiredExp;
            Instance.currentLevel++;
            Instance.upgradeExperience = (int)(Instance.upgradeExperience * 1.5);

            Instance.RaiseExperienceUpdate();
        }

        // ============================================================
        // 经验球非网络化 RPC 处理（方案二）
        // ============================================================

        /// <summary>
        /// 由 AppRpcBridge.RPC_SpawnExpBall 调用
        /// 每个客户端在本地生成一个经验球（非网络对象）
        /// </summary>
        public static void HandleSpawnExpBallRPC(uint ballId, Vector3 position, int expValue)
        {
            if (Instance == null) return;
            Instance.SpawnLocalExpBall(ballId, position, expValue);
        }

        /// <summary>
        /// 由 AppRpcBridge.RPC_ClaimExpBall 调用（仅房主执行）
        /// 处理经验球认领：去重检查 → 加经验 → 广播隐藏
        /// </summary>
        public static void HandleClaimExpBallRPC(uint ballId, int expValue)
        {
            if (Instance == null) return;
            Instance.ClaimLocalExpBall(ballId, expValue);
        }

        /// <summary>
        /// 由 AppRpcBridge.RPC_ExpBallCollected 调用
        /// 所有客户端隐藏对应的本地经验球
        /// </summary>
        public static void HandleExpBallCollectedRPC(uint ballId)
        {
            if (Instance == null) return;
            Instance.HideLocalExpBall(ballId);
        }

        // ── 实例方法 ──

        /// <summary>
        /// 生成一个全局唯一的 ballId（仅房主调用）
        /// </summary>
        public uint GenerateBallId()
        {
            return nextBallId++;
        }

        private void SpawnLocalExpBall(uint ballId, Vector3 position, int expValue)
        {
            var poolManager = ServiceLocator.Get<ObjectPoolManager>();
            if (poolManager == null)
            {
                Debug.LogWarning("[ExperienceManager] ObjectPoolManager 不可用，无法生成经验球");
                return;
            }

            var ballObj = poolManager.GetFromPoolAndActivate(PoolConst.ExperienceBall_Blue_Local, position);
            if (ballObj == null)
            {
                Debug.LogWarning($"[ExperienceManager] 本地经验球池 {PoolConst.ExperienceBall_Blue_Local} 为空");
                return;
            }

            var ball = ballObj.GetComponent<ExperienceBallBase>();
            if (ball == null)
            {
                poolManager.ReturnToPool(PoolConst.ExperienceBall_Blue_Local, ballObj);
                return;
            }

            ball.Setup(ballId, expValue);
            activeExpBalls[ballId] = ballObj;
        }

        private void ClaimLocalExpBall(uint ballId, int expValue)
        {
            // 去重检查：已认领过则忽略
            if (!claimedBalls.Add(ballId))
            {
                Debug.Log($"[ExperienceManager] 球 {ballId} 已被认领，忽略重复请求");
                return;
            }

            // 加经验（AddExperience 内部会检查 IsMasterClient）
            AddExperience(expValue);

            // 广播隐藏此球到所有客户端
            NetworkServiceLocator.ObjectService.InvokeRPC(
                AppRpcBridge.Instance, "RPC_ExpBallCollected",
                NetworkTarget.All, (int)ballId);
        }

        private void HideLocalExpBall(uint ballId)
        {
            if (!activeExpBalls.TryGetValue(ballId, out var ballObj))
            {
                // 球可能已被拾取者本地回收，属正常情况
                return;
            }

            activeExpBalls.Remove(ballId);

            var poolManager = ServiceLocator.Get<ObjectPoolManager>();
            if (poolManager != null)
            {
                poolManager.ReturnToPool(PoolConst.ExperienceBall_Blue_Local, ballObj);
            }
            else
            {
                Destroy(ballObj);
            }
        }

        public void SetExperience(int experience)
        {
            if (!EventChannelLocator.MainContainer.gameSettings.IsTest && !NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                return;
            }

            currentExperience = experience;
            RaiseExperienceUpdate();

            CheckAndQueueUpgrades();
            if (pendingLevelUps.Count > 0 && !isProcessingLevelUp)
            {
                StartLevelUpSequence();
            }
        }

        public int GetCurrentLevel()
        {
            return currentLevel;
        }

        public int GetCurrentExperience()
        {
            return currentExperience;
        }
        #endregion
    }
}

using System.Collections;
