        {
            int currentCount = 0;
            EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                PoolOperationData.CreateGetPoolCount(poolName, (c) => currentCount = c));
            if (currentCount == 0)
            {
                EventChannelLocator.MainContainer.poolOperationChannel.Raise(
                    PoolOperationData.CreateAddMultiple(poolName, prefab, count));
            }
        }

