    /// - 继承 PlayerController，父类已处理通用频道注册（cardReceivedChannel / skillQueryChannel / sceneLoaded）
    /// - 子类只需重写需要个性化处理的方法
    /// - 实际逻辑部分当前为空，请根据角色设计填充
    /// </summary>
    public class BingNv : PlayerController
    {
        // ========== 测试 ==========
        [SerializeField]
